const fs = require('fs');
const zlib = require('zlib');

function readDocx(filepath) {
  const buf = fs.readFileSync(filepath);
  const results = [];
  let offset = 0;

  while (offset < buf.length - 4) {
    // Look for local file header signature
    if (buf.readUInt32LE(offset) === 0x04034b50) {
      const fnameLen = buf.readUInt16LE(offset + 26);
      const extraLen = buf.readUInt16LE(offset + 28);
      const compMethod = buf.readUInt16LE(offset + 8);
      const compSize = buf.readUInt32LE(offset + 18);
      const fname = buf.toString('utf8', offset + 30, offset + 30 + fnameLen);
      const dataStart = offset + 30 + fnameLen + extraLen;

      if (fname.includes('document') && fname.endsWith('.xml')) {
        const compData = buf.slice(dataStart, dataStart + compSize);
        let content;
        if (compMethod === 8) {
          content = zlib.inflateRawSync(compData).toString('utf8');
        } else {
          content = compData.toString('utf8');
        }
        // Extract text between xml tags
        const texts = content.match(/>([^<]+)</g);
        if (texts) {
          const joined = texts.map(t => t.slice(1, -1).trim()).filter(Boolean).join(' ');
          results.push(joined);
        }
      }
      offset = dataStart + compSize;
    } else {
      offset++;
    }
  }
  return results.join(' ');
}

const files = fs.readdirSync('.').filter(f => f.endsWith('.docx'));
for (const f of files) {
  const text = readDocx(f);
  console.log('=== ' + f + ' ===');
  console.log(text.substring(0, 500));
  console.log();
}
