cd /workspace/testbed/docs && node -e "
const fs = require('fs');
const zlib = require('zlib');
const PDFDocument = require('pdfkit');

// --- Extract text from docx ---
const buf = fs.readFileSync('customer_report.docx');
let offset = 0;
let lines = [];

while (offset < buf.length - 4) {
  if (buf.readUInt32LE(offset) === 0x04034b50) {
    const fnameLen = buf.readUInt16LE(offset + 26);
    const extraLen = buf.readUInt16LE(offset + 28);
    const compMethod = buf.readUInt16LE(offset + 8);
    const compSize = buf.readUInt32LE(offset + 18);
    const fname = buf.toString('utf8', offset + 30, offset + 30 + fnameLen);
    const dataStart = offset + 30 + fnameLen + extraLen;

    if (fname.includes('document') && fname.endsWith('.xml')) {
      const compData = buf.slice(dataStart, dataStart + compSize);
      const content = compMethod === 8
        ? zlib.inflateRawSync(compData).toString('utf8')
        : compData.toString('utf8');
      const texts = content.match(/>([^<]+)</g);
      if (texts) {
        lines = texts.map(t => t.slice(1, -1).trim()).filter(Boolean);
      }
    }
    offset = dataStart + compSize;
  } else {
    offset++;
  }
}

// --- Build PDF ---
const doc = new PDFDocument({ margin: 50 });
const output = fs.createWriteStream('customer_report.pdf');
doc.pipe(output);

for (const line of lines) {
  if (line === 'Customer Activity Report') {
    // Title
    doc.fontSize(20).font('Helvetica-Bold').text(line, { align: 'center' });
    doc.moveDown(1);
  } else if (/^(Maya Chen|Jordan Alvarez|Evan Parker|Nina Patel|Alicia Morgan|Sofia Ramirez)$/.test(line)) {
    // Customer name heading
    doc.moveDown(0.5);
    doc.fontSize(14).font('Helvetica-Bold').text(line);
  } else if (line.startsWith('Email:')) {
    doc.fontSize(10).font('Helvetica').text(line);
    doc.moveDown(0.3);
  } else if (line.startsWith('Order ORD-')) {
    doc.fontSize(10).font('Helvetica-Bold').text(line);
  } else if (line.startsWith('Items:')) {
    doc.fontSize(10).font('Helvetica').text(line);
    doc.moveDown(0.3);
  } else {
    doc.fontSize(10).font('Helvetica').text(line);
  }
}

doc.end();
output.on('finish', () => {
  const size = fs.statSync('customer_report.pdf').size;
  console.log('PDF created: customer_report.pdf (' + size + ' bytes)');
});
